BEGIN TRANSACTION;
CREATE TABLE balances_and_quotas (
            msisdn TEXT NOT NULL,
            id TEXT NOT NULL,
            balance_ves REAL NOT NULL DEFAULT 0.00,
            balance_usd_equiv REAL NOT NULL DEFAULT 0.00,
            remaining_data_mb INTEGER NOT NULL DEFAULT 0,
            total_quota_mb INTEGER NOT NULL DEFAULT 0,
            billing_cutoff_date TEXT NOT NULL,
            days_overdue INTEGER NOT NULL DEFAULT 0,
            last_sync_at TEXT NOT NULL,
            PRIMARY KEY (msisdn, id)
        );
CREATE TABLE banks_sudeban (
            bank_code TEXT PRIMARY KEY,
            bank_name TEXT NOT NULL,
            short_name TEXT NOT NULL,
            c2p_enabled INTEGER NOT NULL DEFAULT 1,
            is_active INTEGER NOT NULL DEFAULT 1
        );
CREATE TABLE churn_metrics (
            id TEXT PRIMARY KEY,
            msisdn TEXT NOT NULL,
            churn_score REAL NOT NULL,
            risk_segment TEXT NOT NULL,
            days_without_recharge INTEGER NOT NULL DEFAULT 0,
            complaints_count_30d INTEGER NOT NULL DEFAULT 0,
            data_drop_pct REAL NOT NULL DEFAULT 0.00,
            recommended_action TEXT NOT NULL DEFAULT 'NO_ACTION',
            coupon_code_offered TEXT,
            evaluated_at TEXT NOT NULL
        );
CREATE TABLE eir_security_events (
            ticket_id TEXT PRIMARY KEY,
            msisdn TEXT NOT NULL,
            imei TEXT NOT NULL,
            imsi TEXT NOT NULL,
            event_type TEXT NOT NULL,
            reason TEXT NOT NULL,
            reporting_agent TEXT NOT NULL DEFAULT 'ANTIGRAVITY_MCP_AGENT',
            police_report_number TEXT,
            created_at TEXT NOT NULL
        );
CREATE TABLE financial_transactions (
            executed_at TEXT NOT NULL,
            reference_id TEXT NOT NULL,
            msisdn TEXT NOT NULL,
            bank_code TEXT NOT NULL,
            amount_ves REAL NOT NULL,
            amount_usd REAL NOT NULL,
            bcv_rate_applied REAL NOT NULL,
            payment_method TEXT NOT NULL DEFAULT 'PAGO_MOVIL_C2P',
            status TEXT NOT NULL DEFAULT 'COMPLETADO',
            payer_cid_masked TEXT NOT NULL,
            PRIMARY KEY (executed_at, reference_id),
            FOREIGN KEY (bank_code) REFERENCES banks_sudeban(bank_code)
        );
CREATE TABLE geo_pois (
            id TEXT PRIMARY KEY,
            osm_id INTEGER,
            name TEXT NOT NULL,
            category TEXT NOT NULL,       -- 'farmacia', 'salud_clinica', 'comercio', 'edificio_corporativo', 'perros_calientes'
            sub_category TEXT,           -- 'hospital', 'farmacia_cadena', 'torre_oficinas', etc.
            state TEXT NOT NULL,         -- 'Distrito Capital', 'Miranda', etc.
            municipality TEXT NOT NULL,  -- 'Chacao', 'Baruta', etc.
            parish TEXT NOT NULL,        -- 'Chacao', 'Leoncio Martínez', etc.
            latitude REAL NOT NULL,
            longitude REAL NOT NULL,
            address TEXT NOT NULL,
            phone TEXT,
            opening_hours TEXT,
            emergency_service INTEGER DEFAULT 0,
            metadata_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE pii_vault (
            id TEXT PRIMARY KEY,
            subscriber_id TEXT NOT NULL UNIQUE,
            encrypted_cid TEXT NOT NULL,
            encrypted_full_name TEXT NOT NULL,
            encrypted_email TEXT,
            encrypted_address TEXT,
            key_version TEXT NOT NULL DEFAULT 'v1',
            updated_at TEXT NOT NULL,
            FOREIGN KEY (subscriber_id) REFERENCES subscribers(id) ON DELETE CASCADE
        );
CREATE TABLE product_plans (
            plan_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            commercial_code TEXT NOT NULL UNIQUE,
            category TEXT NOT NULL DEFAULT 'PREPAGO',
            data_quota_mb INTEGER NOT NULL DEFAULT 0,
            voice_minutes INTEGER NOT NULL DEFAULT 0,
            sms_quota INTEGER NOT NULL DEFAULT 0,
            price_usd REAL NOT NULL,
            is_active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        );
CREATE TABLE prospect_trial_limits (
        msisdn TEXT PRIMARY KEY,
        carrier TEXT NOT NULL,
        tokens_used INTEGER NOT NULL DEFAULT 0,
        monthly_queries INTEGER NOT NULL DEFAULT 0,
        last_query_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE semantic_cache_entries (
                    cache_key TEXT PRIMARY KEY,
                    normalized_prompt TEXT NOT NULL,
                    response_text TEXT NOT NULL,
                    intent_category TEXT NOT NULL,
                    estimated_tokens_saved INTEGER NOT NULL DEFAULT 0,
                    created_at_utc REAL NOT NULL,
                    expires_at_utc REAL NOT NULL,
                    hit_count INTEGER NOT NULL DEFAULT 0
                );
CREATE TABLE subscribers (
            id TEXT PRIMARY KEY,
            blind_index_cid TEXT NOT NULL UNIQUE,
            customer_type TEXT NOT NULL DEFAULT 'NATURAL',
            status TEXT NOT NULL DEFAULT 'ACTIVO',
            segment TEXT NOT NULL DEFAULT 'PREPAGO_MASIVO',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE telco_lines (
            msisdn TEXT PRIMARY KEY,
            subscriber_id TEXT NOT NULL,
            imsi TEXT NOT NULL,
            iccid TEXT NOT NULL,
            imei TEXT NOT NULL,
            plan_id TEXT NOT NULL,
            cell_id TEXT NOT NULL DEFAULT 'CAR-CCS-ENB-001',
            status TEXT NOT NULL DEFAULT 'ACTIVO',
            last_sim_swap_at TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (subscriber_id) REFERENCES subscribers(id),
            FOREIGN KEY (plan_id) REFERENCES product_plans(plan_id)
        );
CREATE TABLE usage_records_cdr (
            event_timestamp TEXT NOT NULL,
            id TEXT NOT NULL,
            msisdn TEXT NOT NULL,
            event_type TEXT NOT NULL,
            data_volume_bytes INTEGER NOT NULL DEFAULT 0,
            duration_seconds INTEGER NOT NULL DEFAULT 0,
            cell_id TEXT NOT NULL,
            status_code TEXT NOT NULL DEFAULT 'SUCCESS',
            PRIMARY KEY (event_timestamp, id)
        );
CREATE INDEX idx_sub_blind ON subscribers(blind_index_cid);
CREATE INDEX idx_telco_sub ON telco_lines(subscriber_id);
CREATE INDEX idx_ft_ref ON financial_transactions(reference_id);
CREATE INDEX idx_cdr_msisdn ON usage_records_cdr(msisdn);
CREATE INDEX idx_churn_msisdn ON churn_metrics(msisdn);
CREATE INDEX idx_geo_pois_lat_lon ON geo_pois(latitude, longitude);
CREATE INDEX idx_geo_pois_cat_muni ON geo_pois(category, municipality);
CREATE INDEX idx_semantic_cache_expires 
                ON semantic_cache_entries(expires_at_utc);
CREATE INDEX idx_geo_pois_state ON geo_pois(state);
COMMIT;
